#include <bits/stdc++.h>
using namespace std;

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<int> ksz(n);
    vector<vector<pair<int,int>>> raw(n);
    int totalCells = 0;
    for(int i = 0; i < n; i++){
        cin >> ksz[i];
        raw[i].resize(ksz[i]);
        for(int j = 0; j < ksz[i]; j++) cin >> raw[i][j].first >> raw[i][j].second;
        totalCells += ksz[i];
    }

    // flip f: if f=1, negate x. Then rotate r times 90° CCW: (x,y)->(-y,x)
    // Then normalize so min coords are 0
    auto transform = [](const vector<pair<int,int>>& cells, int r, int f) -> vector<pair<int,int>> {
        vector<pair<int,int>> res;
        for(auto [x, y] : cells){
            int tx = x, ty = y;
            if(f) tx = -tx;
            for(int i = 0; i < r; i++){
                int nx = -ty, ny = tx;
                tx = nx; ty = ny;
            }
            res.push_back({tx, ty});
        }
        int minx = INT_MAX, miny = INT_MAX;
        for(auto& [x,y] : res){ minx = min(minx,x); miny = min(miny,y); }
        for(auto& [x,y] : res){ x -= minx; y -= miny; }
        return res;
    };

    int W = max(20, (int)ceil(sqrt((double)totalCells) * 1.5));

    vector<int> height(W + 50, 0);
    set<pair<int,int>> occ;

    vector<int> order(n);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b){ return ksz[a] > ksz[b]; });

    vector<int> px(n), py(n), pr(n), pf(n);
    int curH = 0;

    for(int idx = 0; idx < n; idx++){
        int i = order[idx];
        int bestScore = INT_MAX;
        int bx=-1, by=-1, br=0, bf=0;
        vector<pair<int,int>> bestCells;

        for(int f = 0; f < 2; f++) for(int r = 0; r < 4; r++){
            auto cells = transform(raw[i], r, f);
            int mxw = 0, mxh = 0;
            for(auto& [cx,cy] : cells){ mxw = max(mxw,cx); mxh = max(mxh,cy); }
            for(int x = 0; x + mxw < W; x++){
                int minY = 0;
                for(auto& [cx,cy] : cells) minY = max(minY, height[x+cx] - cy);
                int y = max(0, minY);
                bool ok = true;
                for(auto& [cx,cy] : cells) if(occ.count({x+cx,y+cy})){ ok = false; break; }
                if(!ok){ y++; ok=true; for(auto& [cx,cy] : cells) if(occ.count({x+cx,y+cy})){ ok=false; break;} if(!ok) continue; }
                int mh = max(curH, y + mxh + 1);
                int sc = mh * 100000 + y * 1000 + x;
                if(sc < bestScore){ bestScore=sc; bx=x; by=y; br=r; bf=f; bestCells=cells; }
            }
        }
        if(bx < 0){ bx=0; by=curH; br=0; bf=0; bestCells=transform(raw[i],0,0); }
        px[i]=bx; py[i]=by; pr[i]=br; pf[i]=bf;
        for(auto& [cx,cy] : bestCells){ occ.insert({bx+cx,by+cy}); height[bx+cx]=max(height[bx+cx],by+cy+1); }
        int mxh=0; for(auto& [cx,cy] : bestCells) mxh=max(mxh,cy);
        curH = max(curH, by + mxh + 1);
    }

    cout << W << " " << curH << "\n";
    for(int i = 0; i < n; i++) cout << px[i] << " " << py[i] << " " << pr[i] << " " << pf[i] << "\n";
}
